// Initialize company processing session
const triggerData = $input.first().json;
const folderName = triggerData.name || 'Unknown_Company';
const folderId = triggerData.id || null;

// Generate unique company ID
const companyId = `company_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Clean company name
let companyName = folderName;
companyName = companyName
  .replace(/^(new folder|folder|untitled|document)$/i, 'Unknown_Company')
  .replace(/[_-]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (companyName.length < 2) {
  companyName = 'Unknown_Company';
}

console.log('🏢 STARTING DUE DILIGENCE PROCESS');
console.log('='.repeat(50));
console.log(`📁 Company: ${companyName}`);
console.log(`🆔 Company ID: ${companyId}`);
console.log(`📂 Folder ID: ${folderId}`);

return {
  json: {
    company_id: companyId,
    company_name: companyName,
    folder_id: folderId,
    folder_name: folderName,
    processing_status: 'initialized',
    start_time: new Date().toISOString()
  }
};

// Process PDF list and create ingestion items for ALL files
// Get company info from previous processing
const allInputs = $input.all();
let companyInfo = {};

// Find company info from inputs
allInputs.forEach(input => {
    const data = input.json;
    if (data && data.company_id && data.company_name) {
        companyInfo = data;
    }
});

// Fallback if no company info found
if (!companyInfo.company_id) {
    companyInfo = {
        company_id: 'unknown',
        company_name: 'Unknown Company',
        folder_id: null
    };
}
const response = $input.first().json;

const files = (response && response.files) ? response.files : [];

if (!files || !Array.isArray(files) || files.length === 0) {
  console.log('❌ No PDF files found in company folder');
  return {
    json: {
      ...companyInfo,
      error: 'No PDF files found',
      processing_status: 'no_files_found'
    }
  };
}

console.log(`📄 Found ${files.length} PDF files for ingestion`);
files.forEach((file, index) => {
  console.log(`  ${index + 1}. ${file.name} (${file.size} bytes, ID: ${file.id})`);
});

// Force processing of ALL files by returning them as separate items
// This ensures n8n processes each file individually
const fileItems = files.map((file, index) => ({
  json: {
    ...companyInfo,
    file_id: file.id,
    file_name: file.name,
    file_size: file.size,
    file_index: index,
    total_files: files.length,
    processing_status: 'ready_for_ingestion',
    batch_id: `batch_${Date.now()}`,
    file_unique_id: `${file.id}_${index}_${Date.now()}`
  }
}));

console.log(`🚀 Prepared ${fileItems.length} file items for parallel processing`);
return fileItems;

// Create text chunks with guaranteed unique IDs for Pinecone
const extractedData = $input.first().json;
// Get file info from input data flow
const allInputs = $input.all();
let fileInfo = {};

// Find file info from inputs
allInputs.forEach(input => {
    const data = input.json;
    if (data && (data.file_name || data.pdf_files)) {
        fileInfo = data;
    }
});

// Fallback if no file info found
if (!fileInfo.file_name) {
    fileInfo = {
        file_name: 'unknown.pdf',
        file_size: 0,
        company_name: 'Unknown Company'
    };
}

console.log(`📄 Processing chunks for: ${fileInfo.file_name}`);
console.log(`📊 File size: ${fileInfo.file_size || 'unknown'} bytes`);

// Get extracted text
let fullText = '';
if (extractedData && extractedData.data) {
  fullText = extractedData.data;
} else if (typeof extractedData === 'string') {
  fullText = extractedData;
}

if (!fullText || fullText.length < 100) {
  console.error(`❌ Text extraction failed for ${fileInfo.file_name}`);
  return [{
    json: {
      ...fileInfo,
      error: 'Text extraction failed',
      processing_status: 'extraction_failed'
    }
  }];
}

// Create chunks with guaranteed unique IDs
const chunkSize = 1500; // Increased chunk size
const overlap = 300; // Increased overlap
const chunks = [];
const timestamp = Date.now();
const randomSuffix = Math.random().toString(36).substr(2, 9);

// Clean file name for use in IDs
const cleanFileName = fileInfo.file_name
  .replace(/\.pdf$/i, '')
  .replace(/[^a-zA-Z0-9]/g, '_')
  .substring(0, 30); // Limit length

for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
  const chunk = fullText.substring(i, i + chunkSize);
  if (chunk.trim().length > 50) {
    // Create absolutely unique chunk ID with file unique ID
    const chunkId = `${fileInfo.company_id}_${cleanFileName}_${fileInfo.file_unique_id}_chunk${chunks.length}_${timestamp}_${randomSuffix}`;

    chunks.push({
      id: chunkId,
      content: chunk.trim(),
      metadata: {
        company_id: fileInfo.company_id,
        company_name: fileInfo.company_name,
        file_name: fileInfo.file_name,
        file_id: fileInfo.file_id,
        file_unique_id: fileInfo.file_unique_id,
        file_size: fileInfo.file_size || 0,
        chunk_index: chunks.length,
        chunk_id: chunkId,
        total_chunks_this_file: Math.ceil(fullText.length / (chunkSize - overlap)),
        extracted_at: new Date().toISOString(),
        source_type: 'company_pdf',
        ingestion_session: timestamp,
        batch_id: fileInfo.batch_id,
        file_index: fileInfo.file_index,
        total_files: fileInfo.total_files
      }
    });
  }
}

const estimatedPages = Math.max(1, Math.ceil(fullText.length / 2500));

console.log(`📦 Created ${chunks.length} chunks for ${fileInfo.file_name}`);
console.log(`📄 Estimated pages: ${estimatedPages}`);
console.log(`📝 Total characters: ${fullText.length}`);
console.log(`🆔 Sample chunk ID: ${chunks[0]?.id || 'none'}`);

// Return all chunks for this file
return chunks.map(chunk => ({
  json: {
    id: chunk.id,
    pageContent: chunk.content,
    metadata: chunk.metadata,
    company_info: {
      ...fileInfo,
      chunks_created: chunks.length,
      pages_estimated: estimatedPages,
      characters_extracted: fullText.length,
      processing_status: 'chunked_successfully'
    }
  }
}));

// Aggregate ingestion results and prepare for section processing
const allInputs = $input.all();

// Check if we have any inputs
if (!allInputs || allInputs.length === 0) {
  throw new Error('No inputs received from Pinecone Vector Store');
}

// Get company info from first input
const firstInput = allInputs[0].json;
let companyInfo;

// Try different ways to get company info
if (firstInput.company_info) {
  companyInfo = firstInput.company_info;
} else if (firstInput.metadata) {
  companyInfo = {
    company_id: firstInput.metadata.company_id,
    company_name: firstInput.metadata.company_name,
    company_folder_name: firstInput.metadata.company_name,
    company_folder_id: 'unknown'
  };
} else {
  // Fallback
  companyInfo = {
    company_id: 'unknown',
    company_name: 'Unknown Company',
    company_folder_name: 'Unknown',
    company_folder_id: 'unknown'
  };
}

// Count chunks by file
const fileChunkCounts = {};
let totalChunks = 0;

allInputs.forEach(input => {
  let fileName = 'unknown_file';

  if (input.json.metadata && input.json.metadata.file_name) {
    fileName = input.json.metadata.file_name;
  } else if (input.json.company_info && input.json.company_info.file_name) {
    fileName = input.json.company_info.file_name;
  }

  if (!fileChunkCounts[fileName]) {
    fileChunkCounts[fileName] = 0;
  }
  fileChunkCounts[fileName]++;
  totalChunks++;
});

console.log('📊 INGESTION COMPLETE');
console.log('═'.repeat(50));
console.log(`🏢 Company: ${companyInfo.company_name}`);
console.log(`📦 Total Chunks Ingested: ${totalChunks}`);
console.log('📄 Files Processed:');
Object.entries(fileChunkCounts).forEach(([fileName, count]) => {
  console.log(`  • ${fileName}: ${count} chunks`);
});
console.log('═'.repeat(50));

return {
  json: {
    ...companyInfo,
    ingestion_complete: true,
    total_chunks_ingested: totalChunks,
    files_processed: Object.keys(fileChunkCounts).length,
    chunk_counts_by_file: fileChunkCounts,
    processing_status: 'ready_for_sections',
    current_step: 'section_generation',
    ingestion_completed_at: new Date().toISOString()
  }
};

// Collect all section outputs and prepare for PDF generation
const allSections = $input.all();
const companyInfo = $node["Complete Ingestion"].json;

console.log('📋 COLLECTING SECTION OUTPUTS');
console.log('═'.repeat(50));

const sectionResults = [];
let approvedSections = 0;
let failedSections = 0;

allSections.forEach((sectionOutput, index) => {
  const sectionNumber = index + 1;
  const sectionData = sectionOutput.json;

  if (sectionData && sectionData.status === 'approved' && sectionData.content) {
    sectionResults.push({
      section_number: sectionNumber,
      title: sectionData.title || `Section ${sectionNumber}`,
      content: sectionData.content,
      status: 'approved',
      word_count: sectionData.content.length,
      generated_at: sectionData.approved_at || new Date().toISOString()
    });
    approvedSections++;
    console.log(`✅ Section ${sectionNumber}: ${sectionData.title || 'Untitled'} (${sectionData.content.length} chars)`);
  } else {
    sectionResults.push({
      section_number: sectionNumber,
      title: `Section ${sectionNumber} - FAILED`,
      content: 'ERROR: Section generation failed or was not approved.',
      status: 'failed',
      error: sectionData?.error || 'Unknown error'
    });
    failedSections++;
    console.log(`❌ Section ${sectionNumber}: FAILED - ${sectionData?.error || 'Unknown error'}`);
  }
});

console.log('═'.repeat(50));
console.log(`✅ Approved Sections: ${approvedSections}/20`);
console.log(`❌ Failed Sections: ${failedSections}/20`);
console.log('═'.repeat(50));

return {
  json: {
    ...companyInfo,
    sections: sectionResults,
    total_sections: sectionResults.length,
    approved_sections: approvedSections,
    failed_sections: failedSections,
    success_rate: `${((approvedSections / 20) * 100).toFixed(1)}%`,
    processing_status: 'ready_for_pdf_generation',
    current_step: 'pdf_generation',
    sections_completed_at: new Date().toISOString()
  }
};

// Generate final PDF content from all approved sections
const data = $input.first().json;

console.log('📄 GENERATING FINAL PDF');
console.log('═'.repeat(50));

// Create PDF content structure
let pdfContent = '';

// Add title page
pdfContent += `# Due Diligence Report\n\n`;
pdfContent += `**Company:** ${data.company_name}\n\n`;
pdfContent += `**Generated:** ${new Date().toLocaleDateString()}\n\n`;
pdfContent += `**Sections Completed:** ${data.approved_sections}/20 (${data.success_rate})\n\n`;
pdfContent += `**Total Files Analyzed:** ${data.files_processed}\n\n`;
pdfContent += `**Knowledge Base Chunks:** ${data.total_chunks_ingested}\n\n`;
pdfContent += `---\n\n`;

// Add table of contents
pdfContent += `## Table of Contents\n\n`;
data.sections.forEach(section => {
  pdfContent += `${section.section_number}. ${section.title}\n`;
});
pdfContent += `\n---\n\n`;

// Add all sections
data.sections.forEach(section => {
  pdfContent += `## ${section.section_number}. ${section.title}\n\n`;
  pdfContent += `${section.content}\n\n`;

  if (section.status === 'failed') {
    pdfContent += `*Note: This section could not be generated due to: ${section.error}*\n\n`;
  }

  pdfContent += `---\n\n`;
});

// Add generation metadata
pdfContent += `## Generation Metadata\n\n`;
pdfContent += `- **Company ID:** ${data.company_id}\n`;
pdfContent += `- **Processing Started:** ${data.start_time}\n`;
pdfContent += `- **Ingestion Completed:** ${data.ingestion_completed_at}\n`;
pdfContent += `- **Sections Completed:** ${data.sections_completed_at}\n`;
pdfContent += `- **PDF Generated:** ${new Date().toISOString()}\n`;
pdfContent += `- **Total Processing Time:** ${Math.round((new Date() - new Date(data.start_time)) / 1000 / 60)} minutes\n`;

console.log(`📊 PDF Content Generated: ${pdfContent.length} characters`);
console.log(`📄 Sections Included: ${data.sections.length}`);
console.log('═'.repeat(50));

return {
  json: {
    ...data,
    pdf_content: pdfContent,
    pdf_file_name: `Due_Diligence_Report_${data.company_name.replace(/[^a-zA-Z0-9]/g, '_')}_${new Date().toISOString().split('T')[0]}.md`,
    processing_status: 'pdf_content_ready',
    pdf_generated_at: new Date().toISOString()
  }
};

// Save section data (n8n-compatible approach)
const data = $input.first().json;

// Generate unique ID if not present
if (!data.id) {
    data.id = Date.now();
}

// Add timestamps
const record = {
    ...data,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
};

console.log(`✅ Section data prepared for storage`);
console.log(`📊 Section: ${record.section_number || 'unknown'} - ${record.title || 'Unknown Title'}`);
console.log(`🏢 Company: ${record.company_name || 'Unknown Company'}`);

// Return the data - it will be handled by the next node
return { json: record };

// Final completion status and summary
const dbData = $input.first().json;

// Extract data from the input (which contains all the report information)
const reportData = dbData;

const processingTimeMinutes = Math.round((new Date() - new Date(reportData.start_time)) / 1000 / 60);

console.log('🎉 DUE DILIGENCE PROCESS COMPLETE!');
console.log('═'.repeat(60));
console.log(`🏢 Company: ${reportData.company_name}`);
console.log(`📁 Company Folder: ${reportData.company_folder_name || 'Unknown'}`);
console.log(`📄 Files Processed: ${reportData.files_processed || 0}`);
console.log(`📦 Knowledge Chunks: ${reportData.total_chunks_ingested || 0}`);
console.log(`📋 Sections Generated: ${reportData.approved_sections || 0}/20`);
console.log(`✅ Success Rate: ${reportData.success_rate || '0%'}`);
console.log(`⏱️ Total Processing Time: ${processingTimeMinutes} minutes`);
console.log(`📄 Final Report: ${reportData.pdf_file_name || 'Generated'}`);
console.log(`🔗 Report URL: Available in Google Drive`);
console.log('═'.repeat(60));

return {
  json: {
    processing_complete: true,
    company_id: reportData.company_id,
    company_name: reportData.company_name,
    final_status: 'success',
    summary: {
      files_processed: reportData.files_processed || 0,
      chunks_ingested: reportData.total_chunks_ingested || 0,
      sections_generated: `${reportData.approved_sections || 0}/20`,
      success_rate: reportData.success_rate || '0%',
      processing_time_minutes: processingTimeMinutes
    },
    final_report: {
      file_name: reportData.pdf_file_name || 'Due_Diligence_Report.md',
      folder_id: reportData.company_folder_id
    },
    completed_at: new Date().toISOString(),
    status_message: `✅ Due diligence report generated successfully for ${reportData.company_name}`
  }
};
